using WoWSync.Core.Abstractions;
using WoWSync.Core.Detection;
using WoWSync.Core.Tests.Fakes;
using Xunit;

namespace WoWSync.Core.Tests;

public class SqliteReaderTests
{
    private static byte[] Fixture(string name) =>
        File.ReadAllBytes(Path.Combine(AppContext.BaseDirectory, "Fixtures", name));

    [Fact]
    public void Reads_every_row_across_interior_pages_with_overflow_and_all_value_types()
    {
        // Generated by Python's sqlite3 with 1 KB pages: 28 pages, interior b-tree pages, a 5000-char overflow value.
        var table = Assert.Single(new SqliteReader(Fixture("sqlite-stress.db")).ReadTables());

        Assert.Equal("things", table.Name);
        Assert.Equal(["id", "name", "n", "f", "b", "note"], table.Columns);
        Assert.Equal(500, table.Rows.Count);

        var special = new Dictionary<long, object?[]>
        {
            [250] = [250L, "long", 1L << 40, -0.5, Array.Empty<byte>(), new string('L', 5000)],
            [251] = [251L, "small ints", 0L, 0.0, new byte[] { 0 }, ""],
            [252] = [252L, "one", 1L, 1.0, null, null],
            [253] = [253L, "neg24", -8388607L, 3.25, null, "a"],
            [254] = [254L, "neg48", -140737488355327L, 1e300, null, "b"],
        };
        for (int i = 1; i <= 500; i++)
        {
            var row = table.Rows[i - 1];
            var expected = special.TryGetValue(i, out var s)
                ? s
                : [(long)i, $"row {i} ✓", (long)((i % 2 == 0 ? 1 : -1) * i * 1000003), i / 4.0,
                   new byte[] { (byte)(i % 256), 0, 255 }, i % 7 == 0 ? null : new string('x', i % 13)];
            Assert.Equal(expected, row);
        }
    }

    [Fact]
    public void Reads_utf16_text()
    {
        var table = Assert.Single(new SqliteReader(Fixture("sqlite-utf16.db")).ReadTables());
        Assert.Equal(@"D:\Google Drive\My Drive", Assert.Single(table.Rows)[0]);
    }

    [Fact]
    public void Rejects_files_that_are_not_sqlite_or_are_cut_short()
    {
        Assert.Throws<FormatException>(() => new SqliteReader("not a database at all, just text"u8.ToArray()));
        var cut = Fixture("sqlite-stress.db")[..3000];
        Assert.Throws<FormatException>(() => new SqliteReader(cut).ReadTables());
    }

    [Fact]
    public void Column_names_come_from_create_table_and_skip_constraints()
    {
        Assert.Equal(["a", "b c", "d"],
            SqliteReader.ColumnNames("CREATE TABLE x (a INTEGER PRIMARY KEY, \"b c\" TEXT DEFAULT 'q,r', d NUMERIC(10, 2), UNIQUE (a, d), CHECK (d > 0))"));
    }
}

public class DriveDatabaseDetectionTests
{
    private const string Db = @"C:\Users\Player\AppData\Local\Google\DriveFS\root_preference_sqlite.db";

    private static byte[] Fixture(string name) =>
        File.ReadAllBytes(Path.Combine(AppContext.BaseDirectory, "Fixtures", name));

    [Fact]
    public void Mirrored_my_drive_is_found_from_drives_database_before_probing()
    {
        var fs = new InMemoryFileSystem().Bytes(Db, Fixture("drivefs-roots.db"))
            .Dir(@"C:\Users\Player\My Drive").Dir(@"C:\Users\Player\Desktop");

        var result = new DriveDetector(fs, new FakeRegistry(), new FakeEnvironment()).Detect(null);

        Assert.Equal(@"C:\Users\Player\My Drive", result.MyDrivePath);
        Assert.Equal(DetectionSource.DriveFsSettings, result.Source);
        Assert.Contains(result.Attempts, a => a.Contains("registry: none"));
        Assert.Contains(result.Attempts, a => a.Contains("root_preference_sqlite.db: folder paths") && a.Contains(@"C:\Users\Player\Desktop"));
        Assert.Contains(result.Attempts, a => a == @"Drive database: found C:\Users\Player\My Drive");
        Assert.False(fs.FileExists(@"C:\Users\Player\AppData\Local\WoWSync\Temp\root_preference.db.copy"));
    }

    [Fact]
    public void Missing_database_is_reported_and_probing_still_finds_the_folder()
    {
        var fs = new InMemoryFileSystem().Dir(@"C:\Users\Player\My Drive");
        var result = new DriveDetector(fs, new FakeRegistry(), new FakeEnvironment()).Detect(null);
        Assert.Equal(DetectionSource.Probe, result.Source);
        Assert.Contains(result.Attempts, a => a.StartsWith("Drive database not found") && a.Contains("root_preference_sqlite.db"));
    }

    [Fact]
    public void Unreadable_or_locked_database_is_reported_with_the_reason()
    {
        var corrupt = new InMemoryFileSystem().File(Db, "garbage").Dir(@"C:\Users\Player\My Drive");
        var r1 = new DriveDetector(corrupt, new FakeRegistry(), new FakeEnvironment()).Detect(null);
        Assert.Equal(DetectionSource.Probe, r1.Source);
        Assert.Contains(r1.Attempts, a => a.Contains("could not be read") && a.Contains("FormatException"));

        var locked = new InMemoryFileSystem().Bytes(Db, Fixture("drivefs-roots.db")).Dir(@"C:\Users\Player\My Drive");
        locked.Locked.Add(Db);
        var r2 = new DriveDetector(locked, new FakeRegistry(), new FakeEnvironment()).Detect(null);
        Assert.Contains(r2.Attempts, a => a.Contains("could not be read") && a.Contains("IOException"));
    }

    [Fact]
    public void Database_paths_that_no_longer_exist_are_reported()
    {
        var fs = new InMemoryFileSystem().Bytes(Db, Fixture("drivefs-roots.db")).Dir(@"D:\Elsewhere\My Drive");
        var result = new DriveDetector(fs, new FakeRegistry(), new FakeEnvironment(), @"C:\Temp").Detect(null);
        Assert.False(result.Found);
        Assert.Contains(result.Attempts, a => a.Contains("none of those is, or contains, an existing 'My Drive' folder"));
    }
}
